from typing import Protocol

class ServiceError(Exception):
    """Structured error a service returns; raised by the transport."""
    def __init__(self, code: int, message: str):
        self.code = code
        self.message = message
        super().__init__(f"service error {code}: {message}")

class Transport(Protocol):
    """Caller-supplied byte carrier. It performs the call named by
    (service, method) — the verbatim CSIL service and operation names, ready
    to go on the wire unmodified — with the already-encoded request bytes and
    returns the response bytes, or raises ServiceError. The generated client
    owns (de)serialization; the carrier only moves bytes.
    """
    def call(self, service: str, method: str, req: bytes) -> bytes: ...

class EgressClient:
    """Typed client for the EgressService service."""
    def __init__(self, transport: Transport):
        self._transport = transport

    def list_flows(self, req: ListFlowsRequest) -> ListFlowsResponse:
        """list-flows"""
        return ListFlowsResponse.from_cbor(self._transport.call("EgressService", "list-flows", req.to_cbor()))

